// PQ_MEMC_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module PQ_MEMC_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [31:0] c_cur_addr,
  input logic [31:0] c_prev_addr,
  input logic [31:0] c_dst_addr,
  input logic [15:0] c_stride,
  input logic [15:0] c_h_active,
  input logic [15:0] c_v_active,
  input logic  c_memc_en,
  input logic [7:0] c_mv_frac,
  input logic  c_tone_en,
  input logic [31:0] c_meta0,
  input logic [31:0] c_meta1,
  input logic [31:0] c_meta2,
  input logic [31:0] c_meta3,
  input logic [15:0] c_display_peak,
  input logic  c_meta_load,
  input logic  c_start,
  input logic  c_busy,
  input logic  c_err,
  input logic  c_cfg_err,
  input logic  c_params_ok,
  input logic [15:0] c_tone_slope,
  input logic [15:0] c_content_max,
  input logic [15:0] c_lines,
  input logic [31:0] c_cycles,
  input logic  c_done,
  input logic  c_err_irq
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 21;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:20];          // model of every stored word
  logic [1:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_done) m_set[0] = 1'b1;
    if (c_err_irq) m_set[1] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h3;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'h3FF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 14) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 15) m_w[15] <= ((m_w[15] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 16) ? PWDATA & m_be & 32'h3 : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h7C080100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return m_w[14];
      15: return m_w[15];
      16: return 0;
      17: return (32'(c_busy) << 0) | (32'(c_err) << 1) | (32'(c_cfg_err) << 2) | (32'(c_params_ok) << 3);
      18: return (32'(c_tone_slope) << 0) | (32'(c_content_max) << 16);
      19: return (32'(c_lines) << 0);
      20: return (32'(c_cycles) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][1:0] & m_w[2][1:0]))
  `SVA_INV(a_core_cur_addr, c_cur_addr == m_w[5][31:0])
  `SVA_INV(a_core_prev_addr, c_prev_addr == m_w[6][31:0])
  `SVA_INV(a_core_dst_addr, c_dst_addr == m_w[7][31:0])
  `SVA_INV(a_core_stride, c_stride == m_w[8][15:0])
  `SVA_INV(a_core_h_active, c_h_active == m_w[8][31:16])
  `SVA_INV(a_core_v_active, c_v_active == m_w[9][15:0])
  `SVA_INV(a_core_memc_en, c_memc_en == m_w[10][0:0])
  `SVA_INV(a_core_mv_frac, c_mv_frac == m_w[10][8:1])
  `SVA_INV(a_core_tone_en, c_tone_en == m_w[10][9:9])
  `SVA_INV(a_core_meta0, c_meta0 == m_w[11][31:0])
  `SVA_INV(a_core_meta1, c_meta1 == m_w[12][31:0])
  `SVA_INV(a_core_meta2, c_meta2 == m_w[13][31:0])
  `SVA_INV(a_core_meta3, c_meta3 == m_w[14][31:0])
  `SVA_INV(a_core_display_peak, c_display_peak == m_w[15][15:0])
  `SVA_INV(a_core_meta_load, c_meta_load == m_pulse_CMD[0])
  `SVA_INV(a_core_start, c_start == m_pulse_CMD[1])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cur_addr == 32'h0 && c_prev_addr == 32'h0 && c_dst_addr == 32'h0 && c_stride == 16'h0 && c_h_active == 16'h0 && c_v_active == 16'h0 && c_memc_en == 1'h0 && c_mv_frac == 8'h0 && c_tone_en == 1'h0 && c_meta0 == 32'h0 && c_meta1 == 32'h0 && c_meta2 == 32'h0 && c_meta3 == 32'h0 && c_display_peak == 16'h0 && c_meta_load == 1'h0 && c_start == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CUR_ADDR, m_rd && m_map && m_idx == 5)
  `FC(wr_CUR_ADDR, m_wr && m_map && m_idx == 5)
  `FC(rd_PREV_ADDR, m_rd && m_map && m_idx == 6)
  `FC(wr_PREV_ADDR, m_wr && m_map && m_idx == 6)
  `FC(rd_DST_ADDR, m_rd && m_map && m_idx == 7)
  `FC(wr_DST_ADDR, m_wr && m_map && m_idx == 7)
  `FC(rd_GEOM, m_rd && m_map && m_idx == 8)
  `FC(wr_GEOM, m_wr && m_map && m_idx == 8)
  `FC(rd_V_ACTIVE, m_rd && m_map && m_idx == 9)
  `FC(wr_V_ACTIVE, m_wr && m_map && m_idx == 9)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 10)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 10)
  `FC(rd_META0, m_rd && m_map && m_idx == 11)
  `FC(wr_META0, m_wr && m_map && m_idx == 11)
  `FC(rd_META1, m_rd && m_map && m_idx == 12)
  `FC(wr_META1, m_wr && m_map && m_idx == 12)
  `FC(rd_META2, m_rd && m_map && m_idx == 13)
  `FC(wr_META2, m_wr && m_map && m_idx == 13)
  `FC(rd_META3, m_rd && m_map && m_idx == 14)
  `FC(wr_META3, m_wr && m_map && m_idx == 14)
  `FC(rd_DISPLAY_PEAK, m_rd && m_map && m_idx == 15)
  `FC(wr_DISPLAY_PEAK, m_wr && m_map && m_idx == 15)
  `FC(rd_CMD, m_rd && m_map && m_idx == 16)
  `FC(wr_CMD, m_wr && m_map && m_idx == 16)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 17)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 17)
  `FC(rd_TONE, m_rd && m_map && m_idx == 18)
  `FC(wr_TONE, m_wr && m_map && m_idx == 18)
  `FC(rd_LINES, m_rd && m_map && m_idx == 19)
  `FC(wr_LINES, m_wr && m_map && m_idx == 19)
  `FC(rd_CYCLES, m_rd && m_map && m_idx == 20)
  `FC(wr_CYCLES, m_wr && m_map && m_idx == 20)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_DONE_set, m_set[0])
  `FC(irq_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ERR_set, m_set[1])
  `FC(irq_ERR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ERR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ERR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(cmd_meta_load, m_pulse_CMD[0])
  `FC(cmd_start, m_pulse_CMD[1])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind PQ_MEMC_apb PQ_MEMC_apb_sva u_apb_sva (.*);
